@php $title=(string)data_get($item,'title','Sản phẩm');$image=(string)data_get($item,'image',data_get($item,'image_url','/theme-demo/ec903/deal-tea.webp'));$url=(string)data_get($item,'url','#');$price=(float)data_get($item,'price',0);$original=(float)data_get($item,'original_price',0);$discount=$original>$price&&$original>0?(int)round((1-$price/$original)*100):0; @endphp
<article class="f406-product" data-f406-reveal><a class="f406-product__image" href="{{ $url }}">@if($discount>0)<b>-{{ $discount }}%</b>@endif<img src="{{ $image }}" alt="{{ data_get($item,'alt',$title) }}" loading="lazy"></a><h3><a href="{{ $url }}">{{ $title }}</a></h3><div class="f406-price">@if($original>$price)<del>{{ number_format($original,0,',','.') }}đ</del>@endif<strong>{{ $price>0?number_format($price,0,',','.').'đ':'Liên hệ' }}</strong></div><div class="f406-stars">★★★★★</div></article>
